#!/bin/bash
dnf update -y
dnf install -y nodejs
mkdir -p /opt/app
echo "" | base64 -d > /opt/app/app.js
echo "ewogICAgIm5hbWUiOiAidXBsb2FkZXItYXBwIiwKICAgICJ2ZXJzaW9uIjogIjEuMC4wIiwKICAgICJtYWluIjogImFwcC5qcyIsCiAgICAiZGVwZW5kZW5jaWVzIjogewogICAgICAgICJleHByZXNzIjogIl40LjE5LjIiLAogICAgICAgICJtdWx0ZXIiOiAiXjEuNC41LWx0cy4xIiwKICAgICAgICAiQGF3cy1zZGsvY2xpZW50LXMzIjogIl4zLjYwMC4wIgogICAgfQp9" | base64 -d > /opt/app/package.json
cd /opt/app
npm install --omit=dev
cat > /etc/systemd/system/uploader.service << 'SERVICE'
[Unit]
Description=Uploader App
After=network.target

[Service]
Environment=BUCKET_NAME=itmo-444-544-jbenman-fileshare
Environment=AWS_REGION=us-east-2
Environment=PORT=3000
WorkingDirectory=/opt/app
ExecStart=/usr/bin/node /opt/app/app.js
Restart=always
User=ec2-user

[Install]
WantedBy=multi-user.target
SERVICE
chown -R ec2-user:ec2-user /opt/app
systemctl daemon-reload
systemctl enable uploader.service
systemctl start uploader.service
